import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resourcesForCleanup = [];
  const timelinesForCleanup = [];

  // Load the background image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  resourcesForCleanup.push(imageTexture);

  // Create plane geometry (atlas region 512x320 = 1.6:1 aspect ratio)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1);
  resourcesForCleanup.push(planeGeometry);

  // Create basic material for the plane
  const planeMaterial = new THREE.MeshBasicNodeMaterial({
    map: imageTexture,
    transparent: true,
  });
  resourcesForCleanup.push(planeMaterial);

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Apply scene position, rotation, and scale from config
  group.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );

  if (config.sceneRotation) {
    group.rotation.set(
      config.sceneRotation[0],
      config.sceneRotation[1],
      config.sceneRotation[2]
    );
  }

  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale[0],
      config.sceneScale[1],
      config.sceneScale[2]
    );
  }

  // Render text content using font atlas
  if (config.textContent && config.textContent.length > 0 && ctx.fontAtlas) {
    const textContent = config.textContent[0];

    const textMesh = ctx.fontAtlas.createTextMesh({
      text: textContent.text,
      fontSize: textContent.fontSize,
      fontWeight: textContent.fontWeight,
      fontFamily: textContent.fontFamily,
      color: config.colors.ink,
      align: 'center',
      anchor: [0.5, 0.5],
    });

    if (textMesh) {
      // Position text slightly in front of the plane
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Initialize event handlers object (no interactions for this static component)
  group.userData.handlers = {};

  // Define cleanup function
  group.userData.cleanup = () => {
    timelinesForCleanup.forEach(timeline => timeline.kill());
    resourcesForCleanup.forEach(resource => {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    });
  };

  return group;
}
